1	// Builds a pre-filled Google Calendar event-template URL from an extracted
2	// event object — the page → events → calendar-URL pipeline's final step.
3	//
4	// An ES module imported by events-view.js (popup-document only, so it can be a
5	// module — it is never injected into the page). `buildCalendarUrl` and
6	// `formatDatesParam` are exported; the rest are module-private helpers.
7	//
8	// GOTCHAS — read before editing (file-local footguns; see the gcec pack RULES.md's locality
9	// rule for why these live here, not in the central gotchas list):
10	//   * Google Calendar renders the `details` param as HTML, not Markdown. A bare
11	//     `**bold**` shows literal asterisks; a bare URL is auto-linked (so it needs
12	//     no `<a>`). `markdownToHtml` below translates the Markdown that survives
13	//     extraction (Meetup / JSON-LD descriptions) into HTML for exactly this
14	//     reason. (#91, #102)
15	//   * Day-boundary date math must use UTC component math, never local-midnight +
16	//     `toISOString()`. `new Date("YYYY-MM-DDT00:00:00")` is *local* midnight,
17	//     which under a positive UTC offset is the previous UTC day, so
18	//     `toISOString()` reports the wrong adjacent date. `nextDay` below uses
19	//     `Date.UTC(y, m-1, d+1)` + `getUTC*` instead. The UTC/`C.UTF-8` sandbox/CI
20	//     default parses floating times as UTC, so a unit test there won't surface
21	//     the shift — it only shows in a positive-offset locale.
22	//
23	// REFERENCES — external pages on the Calendar URL format this file builds:
24	//   * Build a Google Calendar link — the `calendar/render?action=TEMPLATE`
25	//     params used here: https://sadev.co.za/build-google-calendar-link
26	//   * List of tz database time zones — IANA zone names for the `ctz` param:
27	//     https://en.wikipedia.org/wiki/List_of_tz_database_time_zones
28	//   * Kalinka, a similar add-to-Calendar tool: https://kalinka.tardate.com/
29	//   * SO: create a link to add a calendar entry (Google/Outlook/etc.):
30	//     https://stackoverflow.com/questions/5831877/how-do-i-create-a-link-to-add-an-entry-to-a-calendar
31	
32	import { GCalConfig } from "../config.js";
33	
34	const CALENDAR_RENDER_URL = "https://calendar.google.com/calendar/render";
35	
36	// Build the Calendar template URL for one event INSTANCE. An event carries its
37	// timing in `times[]` (the multi-instance model); `instanceIndex` selects which
38	// showing to schedule — an instance varies by date/time AND optionally its own
39	// `location` (a touring show's venue), so the `dates` param and the `location`
40	// param are taken from the chosen instance (location falling back to the event
41	// level), while title/description/ctz come from the event. A flat event ({ start, end,
42	// eventLengthInMinutes } on the object itself) is still accepted — it's treated
43	// as its own single instance — so existing single-occurrence callers and tests
44	// need no change.
45	export function buildCalendarUrl(data, tab, instanceIndex = 0) {
46	  const instance = (data.times && data.times[instanceIndex]) || data;
47	
48	  const params = new URLSearchParams();
49	  params.set("action", "TEMPLATE");
50	
51	  const title = data.title || tab.title || GCalConfig.defaultEventTitle;
52	  params.set("text", title);
53	
54	  const dates = formatDatesParam(instance.start, instance.end, instance.eventLengthInMinutes);
55	  if (dates) params.set("dates", dates);
56	  if (data.ctz) params.set("ctz", data.ctz);
57	  // Location is per-instance in the multi-instance model (a showing at its own
58	  // venue overrides the event's shared location); fall back to the event level.
59	  const location = instance.location || data.location;
60	  if (location) params.set("location", location);
61	
62	  // The details field always starts with a link back to the original event
63	  // page, followed by the full extracted description. It is added LAST so that
64	  // enforcing the overall URL-length cap below shortens the description rather
65	  // than truncating any of the other fields.
66	  let details = markdownToHtml(data.description || "");
67	  const link = sourceLink(tab);
68	  details = (link ? link + "\n\n" : "") + details;
69	  params.set("details", details.trim());
70	
71	  return fitUrlToLimit(params);
72	}
73	
74	// Build the template URL from `params` and, if it exceeds
75	// GCalConfig.maxEventUrlLength, shorten the trailing `details` value until the
76	// whole (URL-encoded) URL fits. details is the last param, so only it is
77	// trimmed; every other field is kept in full. Trimming works on the actual
78	// encoded URL length (not raw characters), so multi-byte/encoded text counts
79	// for what it really costs.
80	function fitUrlToLimit(params) {
81	  const urlFor = (details) => {
82	    params.set("details", details);
83	    return `${CALENDAR_RENDER_URL}?${params.toString()}`;
84	  };
85	
86	  const details = params.get("details") || "";
87	  let url = urlFor(details);
88	  if (url.length <= GCalConfig.maxEventUrlLength) return url;
89	
90	  // Longest prefix of details whose encoded URL fits the cap. Avoid ending on a
91	  // lone surrogate (a split emoji/code point), which would otherwise be encoded
92	  // as a replacement character.
93	  let lo = 0;
94	  let hi = details.length;
95	  while (lo < hi) {
96	    const mid = Math.ceil((lo + hi) / 2);
97	    if (urlFor(details.slice(0, mid)).length <= GCalConfig.maxEventUrlLength) lo = mid;
98	    else hi = mid - 1;
99	  }
100	  if (lo > 0 && lo < details.length) {
101	    const code = details.charCodeAt(lo - 1);
102	    if (code >= 0xd800 && code <= 0xdbff) lo -= 1; // don't keep a dangling high surrogate
103	  }
104	
105	  if (lo === 0) {
106	    // Not even an empty details value leaves room under the cap; drop the field.
107	    params.delete("details");
108	    return `${CALENDAR_RENDER_URL}?${params.toString()}`;
109	  }
110	  return urlFor(details.slice(0, lo));
111	}
112	
113	// The link placed at the top of the details field for a given tab. Google
114	// Calendar autolinks a bare URL in the details field, so it's emitted as plain
115	// text. On meetup.com, event URLs often carry tracking query parameters
116	// (recId, recSource, searchId, ...); strip them entirely so the link points at
117	// the clean canonical URL, e.g.
118	//   https://www.meetup.com/group/events/123
119	function sourceLink(tab) {
120	  if (!tab.url) return "";
121	  let url;
122	  try {
123	    url = new URL(tab.url);
124	  } catch (e) {
125	    return tab.url;
126	  }
127	  const host = url.hostname.replace(/^www\./, "");
128	  if (/(^|\.)meetup\.com$/.test(host)) {
129	    return `${url.origin}${url.pathname.replace(/\/+$/, "")}`;
130	  }
131	  return tab.url;
132	}
133	
134	// Markdown survives extraction (e.g. Meetup's description, whose inline JSON
135	// state and JSON-LD both carry markdown). Google Calendar renders the details
136	// field as HTML, not markdown, so translate the markdown we see into HTML:
137	//   - links [text](url) -> <a href="url">text</a>, but only when `url` is a
138	//     safe scheme (http/https/mailto). The description is page-controlled, so a
139	//     `[x](javascript:...)` would otherwise emit `<a href="javascript:...">`
140	//     into Google Calendar's HTML-rendered details — don't build a dangerous
141	//     scheme from untrusted input; leave any other `[text](url)` literal. A bare
142	//     `[text]` with no following `(url)` doesn't match and stays literal too.
143	//   - bold **text** -> <b>text</b>, but only when each `**` is an isolated
144	//     pair (not part of a longer run of asterisks) wrapping star-free,
145	//     single-line text. That keeps star ratings (e.g. edfringe reviews'
146	//     "***** (Scotsman)"), a stray/unmatched `**`, and `***bold-italic***`
147	//     literal rather than mangling them.
148	function markdownToHtml(text) {
149	  return text
150	    .replace(/\[([^\]]+)\]\(([^)\s]+)\)/g, (match, label, url) =>
151	      isSafeLinkUrl(url) ? `<a href="${url}">${label}</a>` : match
152	    )
153	    .replace(/(?<!\*)\*\*(?!\*)([^\n*]+?)\*\*(?!\*)/g, "<b>$1</b>");
154	}
155	
156	// Whether a markdown link's URL is safe to emit as an <a href>. Allows only
157	// http/https/mailto and scheme-relative (//host) / relative URLs; rejects
158	// javascript:, data:, vbscript:, and any other scheme. A bare host like
159	// "example.com/x" has no scheme and is treated as relative (kept) — matching how
160	// Google Calendar would render it; the guard exists to block dangerous schemes,
161	// not to validate link reachability.
162	function isSafeLinkUrl(url) {
163	  const scheme = /^([a-z][a-z0-9+.-]*):/i.exec(url);
164	  if (!scheme) return true; // no scheme -> relative/scheme-relative, safe
165	  return ["http", "https", "mailto"].includes(scheme[1].toLowerCase());
166	}
167	
168	// Build the `dates` parameter for the TEMPLATE URL:
169	//   timed:   YYYYMMDDTHHMMSS/YYYYMMDDTHHMMSS  (floating, placed by ctz or the
170	//            user's calendar tz)
171	//            or with trailing Z when the source gave an absolute instant
172	//   all-day: YYYYMMDD/YYYYMMDD               (end date exclusive)
173	//
174	// Extractors that know the event's timezone already hand us floating local
175	// times (see GCal.localizeToZone), so a known-timezone event reaches here as a
176	// floating start/end and its ctz param places it. An offset/Z that survives to
177	// here is an event with no known timezone, and is pinned to a UTC instant.
178	//
179	// When `eventLengthInMinutes` is supplied it is preferred over
180	// `defaultEventDurationMs` when the end is missing or invalid, and it can also
181	// derive a missing start from a known end (timed events only — it is ignored
182	// for all-day events where a minute duration has no meaning).
183	export function formatDatesParam(start, end, eventLengthInMinutes) {
184	  if (!start && !end) return "";
185	
186	  if (start && /^\d{4}-\d{2}-\d{2}$/.test(start)) {
187	    // All-day event: eventLengthInMinutes doesn't apply to date-only values.
188	    const endDay = /^\d{4}-\d{2}-\d{2}$/.test(end || "") ? end : start;
189	    return `${compactDay(start)}/${compactDay(nextDay(endDay))}`;
190	  }
191	
192	  // Determine offset presence from whichever bound we have.
193	  const hasOffset = /(?:Z|[+-]\d{2}:?\d{2})$/i.test(start || end || "");
194	  let startDate = start ? new Date(start) : null;
195	  let endDate = end ? new Date(end) : null;
196	
197	  // Derive a missing start from end + length (timed events only).
198	  if ((!startDate || isNaN(startDate)) && endDate && !isNaN(endDate) && eventLengthInMinutes) {
199	    startDate = new Date(endDate.getTime() - eventLengthInMinutes * 60000);
200	  }
201	
202	  if (!startDate || isNaN(startDate)) return "";
203	
204	  if (!endDate || isNaN(endDate) || endDate <= startDate) {
205	    const durationMs = eventLengthInMinutes != null
206	      ? eventLengthInMinutes * 60000
207	      : GCalConfig.defaultEventDurationMs;
208	    endDate = new Date(startDate.getTime() + durationMs);
209	  }
210	
211	  return hasOffset
212	    ? `${compactUTC(startDate)}/${compactUTC(endDate)}`
213	    : `${compactLocal(startDate)}/${compactLocal(endDate)}`;
214	}
215	
216	function pad(n) {
217	  return String(n).padStart(2, "0");
218	}
219	
220	function compactDay(isoDay) {
221	  return isoDay.replace(/-/g, "");
222	}
223	
224	function nextDay(isoDay) {
225	  const [y, m, d] = isoDay.split("-").map(Number);
226	  const next = new Date(Date.UTC(y, m - 1, d + 1));
227	  return `${next.getUTCFullYear()}-${pad(next.getUTCMonth() + 1)}-${pad(next.getUTCDate())}`;
228	}
229	
230	function compactUTC(d) {
231	  return (
232	    `${d.getUTCFullYear()}${pad(d.getUTCMonth() + 1)}${pad(d.getUTCDate())}` +
233	    `T${pad(d.getUTCHours())}${pad(d.getUTCMinutes())}${pad(d.getUTCSeconds())}Z`
234	  );
235	}
236	
237	function compactLocal(d) {
238	  return (
239	    `${d.getFullYear()}${pad(d.getMonth() + 1)}${pad(d.getDate())}` +
240	    `T${pad(d.getHours())}${pad(d.getMinutes())}${pad(d.getSeconds())}`
241	  );
242	}
